from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import TypedDict, cast


class BenchmarkEntry(TypedDict):
    """Relevant fields from a Google Benchmark entry."""

    name: str
    real_time: float
    cpu_time: float
    time_unit: str


class BenchmarkFile(TypedDict):
    """Relevant fields from a Google Benchmark result file."""

    benchmarks: list[BenchmarkEntry]


TIME_UNIT_NS = {
    "ns": 1.0,
    "us": 1_000.0,
    "ms": 1_000_000.0,
    "s": 1_000_000_000.0,
}


def parse_args() -> argparse.Namespace:
    """Parse command-line arguments."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--baseline", required=True, type=Path, help="Baseline Google Benchmark JSON file")
    parser.add_argument("--candidate", required=True, type=Path, help="Candidate Google Benchmark JSON file")
    return parser.parse_args()


def load_benchmarks(path: Path) -> dict[str, BenchmarkEntry]:
    """Load benchmark entries by name from a Google Benchmark JSON file."""
    if not path:
        raise ValueError("benchmark JSON path is empty")
    if not path.exists():
        raise FileNotFoundError(path)

    with path.open(encoding="utf-8") as benchmark_file:
        data = cast(BenchmarkFile, json.load(benchmark_file))

    if "benchmarks" not in data:
        raise ValueError(f"{path}: missing 'benchmarks' list")

    return {entry["name"]: entry for entry in data["benchmarks"]}


def time_ns(entry: BenchmarkEntry) -> float:
    """Return real time in nanoseconds."""
    unit = entry.get("time_unit", "ns")
    if unit not in TIME_UNIT_NS:
        raise ValueError(f"{entry['name']}: unsupported time unit {unit!r}")
    return float(entry["real_time"]) * TIME_UNIT_NS[unit]


def compare(baseline: dict[str, BenchmarkEntry], candidate: dict[str, BenchmarkEntry]) -> int:
    """Write the comparison table and return a process status."""
    baseline_names = set(baseline)
    candidate_names = set(candidate)

    missing_from_candidate = sorted(baseline_names - candidate_names)
    missing_from_baseline = sorted(candidate_names - baseline_names)
    if missing_from_candidate or missing_from_baseline:
        if missing_from_candidate:
            sys.stderr.write("Missing from candidate:\n")
            sys.stderr.write("".join(f"  {name}\n" for name in missing_from_candidate))
        if missing_from_baseline:
            sys.stderr.write("Missing from baseline:\n")
            sys.stderr.write("".join(f"  {name}\n" for name in missing_from_baseline))
        return 1

    rows: list[tuple[str, float, float, float, float]] = []
    for name in sorted(baseline):
        baseline_time = time_ns(baseline[name])
        candidate_time = time_ns(candidate[name])
        delta = candidate_time - baseline_time
        percent = 0.0 if baseline_time == 0.0 else (delta / baseline_time) * 100.0
        rows.append((name, baseline_time, candidate_time, delta, percent))

    name_width = max(len("benchmark"), *(len(row[0]) for row in rows))
    sys.stdout.write(
        f"{'benchmark':<{name_width}}  {'baseline(ns)':>14}  {'candidate(ns)':>14}  "
        f"{'delta(ns)':>14}  {'delta(%)':>9}\n"
    )
    for name, baseline_time, candidate_time, delta, percent in rows:
        sys.stdout.write(
            f"{name:<{name_width}}  {baseline_time:14.3f}  {candidate_time:14.3f}  {delta:14.3f}  {percent:9.2f}\n"
        )

    return 0


def main() -> int:
    """Run the benchmark comparison."""
    args = parse_args()
    try:
        return compare(load_benchmarks(args.baseline), load_benchmarks(args.candidate))
    except (OSError, ValueError, json.JSONDecodeError) as err:
        sys.stderr.write(f"{err}\n")
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
